31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
32	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
33	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
36	import org.springframework.samples.petclinic.mapper.MembershipLevel;
37	import org.springframework.samples.petclinic.mapper.OwnerLocality;
38	import org.springframework.samples.petclinic.mapper.OwnerMapper;
39	import org.springframework.samples.petclinic.mapper.PetMapper;
40	import org.springframework.samples.petclinic.mapper.VisitMapper;
41	import org.springframework.samples.petclinic.model.Owner;
42	import org.springframework.samples.petclinic.model.Pet;
43	import org.springframework.samples.petclinic.model.Visit;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.service.ClinicService;
52	import org.springframework.security.access.prepost.PreAuthorize;
53	import org.springframework.util.StringUtils;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
72	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
73	     * addresses are lower-cased before being stored.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
77	
78	    /** An owner's postcode, when supplied, must be exactly four digits. */
79	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
80	
81	    /**
82	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
83	     * named logger keeps them addressable independently of the class's diagnostic logging.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
86	
87	    /**
88	     * Maximum number of owners a single city may contain. A create that would take the owner's city
89	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
90	     */
91	    private static final int CITY_OWNER_LIMIT = 50;
92	
93	    /**
94	     * Maximum number of owners that may be registered on a single day. A create that would take the
95	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
96	     * have already been created that day - is rejected with a 429.
97	     */
98	    private static final int DAILY_OWNER_LIMIT = 100;
99	
100	    /**
101	     * Number of owners that must already have been created for a given day before the create
102	     * response flags a bulk sign-up. When more than this many owners already share a
103	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
104	     */
105	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
106	
107	    private final ClinicService clinicService;
108	
109	    private final OwnerMapper ownerMapper;
110	
111	    private final PetMapper petMapper;
112	
113	    private final VisitMapper visitMapper;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper) {
119	        this.clinicService = clinicService;
120	        this.ownerMapper = ownerMapper;
121	        this.petMapper = petMapper;
122	        this.visitMapper = visitMapper;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
149	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
154	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
155	     * owner sign-ups.
156	     *
157	     * @param registrationDate the day to inspect, or {@code null}
158	     * @return {@code true} when more than the threshold of owners are registered on that day
159	     */
160	    private boolean isBulkSignupDay(LocalDate registrationDate) {
161	        return registrationDate != null
162	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
169	        validateRequiredFields(ownerFieldsDto);
170	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
174	        owner.setEmail(normalizeEmail(owner.getEmail()));
175	        validateRegistrationDate(owner.getRegistrationDate());
176	        if (owner.getRegistrationDate() == null) {
177	            owner.setRegistrationDate(LocalDate.now());
178	        }
179	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
180	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
181	        owner.setIdentityKey(buildIdentityKey(owner,
182	            Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())));
183	        rejectDuplicateOwner(owner.getIdentityKey());
184	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
185	            throw new OwnerCityFullException(owner.getCity());
186	        }
187	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
188	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
189	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
190	        }
191	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
192	        owner.setCustomerCode(buildCustomerCode(owner));
193	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
194	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
195	        this.clinicService.saveOwner(owner);
196	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
197	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
198	            MembershipLevel.forOwner(owner));
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
201	        headers.setLocation(UriComponentsBuilder.newInstance()
202	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
203	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
204	    }
205	
206	    /**
207	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
208	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
209	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
210	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
211	     * after normalization is still rejected.
212	     *
213	     * @param ownerFieldsDto the submitted owner fields
214	     */
215	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
216	        List<String> missingFields = new ArrayList<>();
217	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
218	            missingFields.add("firstName");
219	        }
220	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
221	            missingFields.add("lastName");
222	        }
223	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
224	            missingFields.add("address");
225	        }
226	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
227	            missingFields.add("city");
228	        }
229	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
230	            missingFields.add("telephone");
231	        }
232	        if (!missingFields.isEmpty()) {
233	            throw new MissingOwnerFieldsException(missingFields);
234	        }
235	    }
236	
237	    /**
238	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
239	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
240	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
241	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
242	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
243	     * whose {@code errors} array lists {@code postcode}.
244	     *
245	     * @param postcode the submitted postcode, or {@code null} when none was supplied
246	     * @param city the owner's city, whose region determines the acceptable postcode range
247	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
248	     */
249	    private void validatePostcode(String postcode, String city) {
250	        if (!StringUtils.hasText(postcode)) {
251	            return;
252	        }
253	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
254	            throw new InvalidOwnerFieldsException(List.of("postcode"));
255	        }
256	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
257	            throw new InvalidOwnerFieldsException(List.of("postcode"));
258	        }
259	    }
260	
261	    /**
262	     * Validates an owner's optional registration date. Registration date is optional, so a missing
263	     * value is accepted (the create later defaults it to the server date). When a value is supplied
264	     * it may not lie in the future: a date later than the server's current date is rejected with a
265	     * 400 whose {@code errors} array lists {@code registrationDate}.
266	     *
267	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
268	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
269	     */
270	    private void validateRegistrationDate(LocalDate registrationDate) {
271	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
272	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
273	        }
274	    }
275	
276	    /**
277	     * Rejects a submitted owner whose derived {@code identityKey} exactly matches an existing owner's.
278	     * All duplicate detection is consolidated into this single key, so a collision is reported to the
279	     * client as a 409 Conflict regardless of which field(s) coincide. Because the telephone is part of
280	     * the key, two owners that differ in telephone can never collide even when they share every other
281	     * component (for example two members of the same household).
282	     *
283	     * @param identityKey the derived identity key of the owner about to be created
284	     */
285	    private void rejectDuplicateOwner(String identityKey) {
286	        boolean duplicate = this.clinicService.findAllOwners().stream()
287	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
288	        if (duplicate) {
289	            throw new DuplicateOwnerIdentityException(identityKey);
290	        }
291	    }
292	
293	    /**
294	     * Derives the owner's {@code identityKey}, the single value through which all duplicate detection is
295	     * expressed. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId},
296	     * where the telephone and email have already been normalized. The household segment carries the
297	     * owner's {@code householdId} only when the owner knowingly belongs to a shared household (the
298	     * request opted in with {@code sharesHousehold}); otherwise it is empty, so an owner is identified
299	     * by telephone and email alone.
300	     *
301	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
302	     * @param sharesHousehold whether the request opted into a shared household
303	     * @return the derived identity key
304	     */
305	    private String buildIdentityKey(Owner owner, boolean sharesHousehold) {
306	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
307	        String household = sharesHousehold ? owner.getHouseholdId() : "";
308	        return owner.getTelephone() + "|" + email + "|" + household;
309	    }
310	
311	    /**
312	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
313	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
314	     * address; the accepted value is lower-cased before it is stored and returned.
315	     *
316	     * @param email the raw email value submitted by the client, or {@code null}
317	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
318	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
319	     */
320	    private String normalizeEmail(String email) {
321	        if (!StringUtils.hasText(email)) {
322	            return email;
323	        }
324	        if (!EMAIL_PATTERN.matcher(email).matches()) {
325	            throw new InvalidOwnerFieldsException(List.of("email"));
326	        }
327	        return email.toLowerCase();
328	    }
329	
330	    /**
331	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
332	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
333	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
334	     *
335	     * @param owner the normalized owner about to be created
336	     * @return the assigned customer code
337	     */
338	    private String buildCustomerCode(Owner owner) {
339	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
340	        return CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
341	    }
342	
343	    /**
344	     * Counts how many owners already exist that share the supplied first and last name, compared
345	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
346	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
347	     *
348	     * @param firstName the submitted owner's first name
349	     * @param lastName the submitted owner's last name
350	     * @return the number of existing owners with the same first and last name, ignoring case
351	     */
352	    private int countNamesakes(String firstName, String lastName) {
353	        return (int) this.clinicService.findAllOwners().stream()
354	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
355	                && lastName.equalsIgnoreCase(existing.getLastName()))
356	            .count();
357	    }
358	
359	    /**
360	     * Counts how many existing owners already belong to the supplied household, identified by its
361	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
362	     * owner is added (this count plus one).
363	     *
364	     * @param householdId the normalized household identifier of the owner being created
365	     * @return the number of existing owners already sharing that {@code householdId}
366	     */
367	    private int countHouseholdMembers(String householdId) {
368	        return (int) this.clinicService.findAllOwners().stream()
369	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
370	            .count();
371	    }
372	
373	    /**
374	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
375	     * enforce the per-city capacity limit when a new owner is created.
376	     *
377	     * @param city the submitted owner's city
378	     * @return the number of existing owners in that city, ignoring case
379	     */
380	    private long countOwnersInCity(String city) {
381	        return this.clinicService.findAllOwners().stream()
382	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
383	            .count();
384	    }
385	
386	    /**
387	     * Counts how many owners have already been created on the supplied registration date. Used to
388	     * enforce the per-day capacity limit when a new owner is created.
389	     *
390	     * @param registrationDate the registration date of the owner being created
391	     * @return the number of existing owners already registered on that date
392	     */
393	    /**
394	     * Rolls a registration date forward to a business day. A registration date must fall on a
395	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
396	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
397	     * from the registration date (such as the membership number's year segment) and the daily
398	     * create-limit therefore use the adjusted date.
399	     *
400	     * @param date the effective registration date, whether supplied or defaulted to the server date
401	     * @return the same date when it is a weekday, otherwise the next Monday
402	     */
403	    private LocalDate toBusinessDay(LocalDate date) {
404	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
405	            date = date.plusDays(1);
406	        }
407	        return date;
408	    }
409	
410	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
411	        return this.clinicService.findAllOwners().stream()
412	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
413	            .count();
414	    }
415	
416	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
417	    @Override
418	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
419	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
420	        if (currentOwner == null) {
421	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
422	        }
423	        currentOwner.setAddress(ownerFieldsDto.getAddress());
424	        currentOwner.setCity(ownerFieldsDto.getCity());
425	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
426	        currentOwner.setLastName(ownerFieldsDto.getLastName());
427	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
428	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
429	        this.clinicService.saveOwner(currentOwner);
430	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Transactional
435	    @Override
436	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
437	        Owner owner = this.clinicService.findOwnerById(ownerId);
438	        if (owner == null) {
439	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
440	        }
441	        this.clinicService.deleteOwner(owner);
442	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
443	    }
444	
445	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
446	    @Override
447	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
448	        Owner owner = this.clinicService.findOwnerById(ownerId);
449	        if (owner == null) {
450	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
451	        }
452	        HttpHeaders headers = new HttpHeaders();
453	        Pet pet = petMapper.toPet(petFieldsDto);
454	        owner.setId(ownerId);
455	        pet.setOwner(owner);
456	        pet.getType().setName(null);
457	        this.clinicService.savePet(pet);
458	        PetDto petDto = petMapper.toPetDto(pet);
459	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
460	            .buildAndExpand(pet.getId()).toUri());
461	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
462	    }
463	
464	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
465	    @Override
466	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
467	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
468	        if (currentOwner != null) {
469	            Pet currentPet = this.clinicService.findPetById(petId);
470	            if (currentPet != null) {
471	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
472	                currentPet.setName(petFieldsDto.getName());
473	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
474	                this.clinicService.savePet(currentPet);
475	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
476	            }
477	        }
478	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
479	    }
480	
481	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
482	    @Override
483	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
484	        HttpHeaders headers = new HttpHeaders();
485	        Visit visit = visitMapper.toVisit(visitFieldsDto);
486	        Pet pet = new Pet();
487	        pet.setId(petId);
488	        visit.setPet(pet);
489	        this.clinicService.saveVisit(visit);
490	        VisitDto visitDto = visitMapper.toVisitDto(visit);
491	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
492	            .buildAndExpand(visit.getId()).toUri());
493	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
494	    }
495	
496	
497	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
498	    @Override
499	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
500	        Owner owner = this.clinicService.findOwnerById(ownerId);
501	        if (owner != null) {
502	            Pet pet = owner.getPet(petId);
503	            if (pet != null) {
504	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
505	            }
506	        }
507	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
508	    }
509	}
