18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "checkDigit",
27	        expression = "java(org.springframework.samples.petclinic.mapper.LuhnCheckDigit.forDigits(owner.getCustomerCode()))")
28	    @Mapping(target = "membershipNumber",
29	        expression = "java(owner.getCustomerCode() + \"-M\" "
30	            + "+ String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
31	    @Mapping(target = "membershipLevel",
32	        expression = "java(org.springframework.samples.petclinic.mapper.MembershipLevel.forOwner(owner))")
33	    @Mapping(target = "locality",
34	        expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.forCustomerCode(owner.getCustomerCode()))")
35	    @Mapping(target = "contactPreference",
36	        expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
